import{_ as r,l as i,o as e,c as n,v as l,p as d,x as o,d as p,i as s,S as P}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"拓扑感知放置","description":"","frontmatter":{"title":"拓扑感知放置","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/topology-aware-placement.md","filePath":"llm/topology-aware-placement.md","lastUpdated":1789023840000}'),c={name:"llm/topology-aware-placement.md"};function h(E,a,m,A,B,_){const t=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="拓扑感知放置" tabindex="-1">拓扑感知放置 <a class="header-anchor" href="#拓扑感知放置" aria-label="Permalink to &quot;拓扑感知放置&quot;">​</a></h1><div class="epigraph"><p>把张量并行和专家并行留在 NVLink 岛上，把流水的阶段边界和数据并行的梯度放到节点间网络；放反了，重叠日历只是在遮挡一条注定更慢的链路。</p><footer>—— 据 Shoeybi 等 Megatron 的高带宽域假设；Lepikhin 等 TPU 网格；MegaScale 的集群放置实践</footer></div><p><a href="/llm/dataloader-pipeline">上一课</a>保证 token 能及时上卡。卡与卡之间的集合通信走哪条物理链路，决定 \\(T_{\\mathrm{comm}}\\) 能不能被 GEMM 盖住。本课不重讲预取槽。缺口是把 DP、TP、PP、EP、SP 这些逻辑组映射到机架、NVLink 域与 IB 分区，使 DualPipe 双流、MoE All-to-All、Ulysses 置换不要挤在同一条过订阅切面上。最后一课把即使放置正确、机器仍会坏的概率写成一等公民。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/tensor-parallel">张量并行</a> 每层多次通信，必须短、胖、稳定，对应 GPU 板内或节点内 NVLink。<a href="/llm/pipeline-parallel">流水线并行</a> 通信次数少、体积是边界激活，适合节点间。MoE 的 All-to-All 对延迟抖动敏感，EP 组应尽量落在同一高带宽域。Ulysses 的 A2A 体积随 \\(s\\) 涨，SP 组同样。数据并行 All-Reduce 可以跨更远，但梯度体积大、可与计算重叠。逻辑上正交的组，物理上若随便 <code>rank % k</code>，会把 TP 跨到 IB。</p><p>TPU 上的网格放置（GShard）从一开始就是拓扑问题。GPU 集群的胖树过订阅使「任意 All-to-All」在满载时崩溃。放置是调度课所有日历的硬件前提。</p><h3 id="双流与保存流量" tabindex="-1">双流与保存流量 <a class="header-anchor" href="#双流与保存流量" aria-label="Permalink to &quot;双流与保存流量&quot;">​</a></h3><p>DualPipe 要双向带宽。异步检查点要对象存储带宽。加载器要读带宽。三者若走同一 NIC，落后者会周期性出现在「刚保存的那几步」。放置也包括 IO 面：训练通信与存储平面分离，或至少错峰。</p><p><span class="marginnote">同一节点多 GPU 的 PCIe 切分也会把「看起来是 NVLink 组」变成假高带宽。应以实际 NCCL 拓扑检测为准，而不是主机名正则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：集群拓扑图（NVLink 岛、机架、leaf-spine、超节点）。输出：rank 到 GPU 的置换。优先满足：<code>TP ⊂ NVLink</code>，<code>EP ⊂ NVLink 或超节点</code>，<code>SP</code> 次之，<code>PP</code> 沿机架深度排列以缩短相邻阶段，<code>DP</code> 跨剩余维。MegaScale 一类工作强调自动探测与校验：作业启动时跑一次小 All-Reduce 环测，发现错位立即失败，而不是训三小时再查。</p><p>换弹性计划时重新跑放置，不要沿用已死节点的 rank 号。热备节点应在同一 NVLink 岛内，否则 shrink 后 TP 组被拆到 IB。</p><h3 id="与日历的联合验收" tabindex="-1">与日历的联合验收 <a class="header-anchor" href="#与日历的联合验收" aria-label="Permalink to &quot;与日历的联合验收&quot;">​</a></h3><p>放置对不对，用通信暴露时间与 P99 栅栏等待验收，而不是用「配置里写了 topology_aware=true」。重叠课的 profiler 是验收工具。</p><p><span class="marginnote">防火墙式的机架隔离（安全域）可能禁止理想放置。应把约束写进计划表，选出次优合法点，而不是静默跨域。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>集合通信的延迟由最慢的那一跳决定。逻辑组的直径必须匹配算法假设的直径。TP 假设直径是 NVLink；一旦直径变成跨 spine，公式里的「可重叠」不再成立。放置是把假设嵌进物理。</p>',17)),(e(),d(P,null,{default:o(()=>[s(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOPO%5B%22NVLink%20%E5%B2%9B%20%2F%20%E6%9C%BA%E6%9E%B6%20%2F%20%E8%83%96%E6%A0%91%22%5D%20--%3E%20MAP%5B%22%E9%80%BB%E8%BE%91%E7%BB%84%E6%98%A0%E5%B0%84%22%5D%0A%20%20MAP%20--%3E%20TP%5B%22TP%20%2F%20EP%20%2F%20SP%20%E5%9C%A8%E5%B2%9B%E5%86%85%22%5D%0A%20%20MAP%20--%3E%20PP%5B%22PP%20%E8%B7%A8%E8%8A%82%E7%82%B9%E7%9B%B8%E9%82%BB%22%5D%0A%20%20MAP%20--%3E%20DP%5B%22DP%20%E7%94%A8%E5%89%A9%E4%BD%99%E7%BB%B4%22%5D%0A%20%20MAP%20--%3E%20IO%5B%22%E5%AD%98%E5%82%A8%E5%B9%B3%E9%9D%A2%E5%88%86%E7%A6%BB%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>放置不增加链路带宽，过订阅仍在。它也不能让坏 GPU 变好。下一课给出万卡上故障成为期望事件的定量图景：即使拓扑完美，MTBF 仍随 \\(N\\) 下降，检查点、弹性、落后者治理是在付概率的账。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲加载槽；只补逻辑并行组到物理链路的映射。</li><li>TP/EP/SP 优先 NVLink；PP 走节点间；DP 更远；IO 面分开。</li><li>启动环测校验；弹性后重放置。</li><li>用暴露时间验收，不信配置布尔。</li><li>出处：Shoeybi et al., Megatron-LM；Lepikhin et al., GShard；Jiang et al., MegaScale。</li></ul>',4))])}const T=r(c,[["render",h]]);export{u as __pageData,T as default};
